#include <algorithm>
#include <cctype>
#include <map>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

struct Key { int vk; bool ctrl{ false }, shift{ false }, alt{ false }; };

namespace
{
    std::string lower(std::string s) { for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c))); return s; }

    std::string trim(const std::string& s)
    {
        const auto b{ s.find_first_not_of(' ') };
        if (b == std::string::npos) return "";
        return s.substr(b, s.find_last_not_of(' ') - b + 1);
    }

    const std::vector<std::pair<std::string, int>>& keyNames()
    {
        static const std::vector<std::pair<std::string, int>> n{
            { "Delete", 0x2E }, { "Insert", 0x2D }, { "Home", 0x24 }, { "End", 0x23 }, { "PageUp", 0x21 }, { "PageDown", 0x22 },
            { "Left", 0x25 }, { "Up", 0x26 }, { "Right", 0x27 }, { "Down", 0x28 }, { "Enter", 0x0D }, { "Esc", 0x1B },
            { "Space", 0x20 }, { "Tab", 0x09 } };
        return n;
    }

    bool parseKey(const std::string& text, Key& out)
    {
        std::vector<std::string> parts;
        std::stringstream in{ text };
        for (std::string p; std::getline(in, p, '+');) parts.push_back(trim(p));
        if (parts.empty() || text.back() == '+') return false;
        Key k{ 0 };
        for (std::size_t i{ 0 }; i + 1 < parts.size(); ++i)
        {
            const std::string m{ lower(parts[i]) };
            bool* flag{ m == "ctrl" || m == "control" ? &k.ctrl : m == "shift" ? &k.shift : m == "alt" ? &k.alt : nullptr };
            if (!flag || *flag) return false;
            *flag = true;
        }
        const std::string p{ lower(parts.back()) };
        if (p.size() == 1 && std::isalnum(static_cast<unsigned char>(p[0]))) k.vk = std::toupper(static_cast<unsigned char>(p[0]));
        else if (p.size() >= 2 && p[0] == 'f' && p[1] != '0' && p.find_first_not_of("0123456789", 1) == std::string::npos && std::stoi(p.substr(1)) <= 12)
            k.vk = 0x70 + std::stoi(p.substr(1)) - 1;
        else
        {
            for (const auto& [name, code] : keyNames()) if (lower(name) == p) k.vk = code;
            if (k.vk == 0) return false;
        }
        out = k;
        return true;
    }

    std::string formatKey(const Key& k)
    {
        std::string out{ std::string(k.ctrl ? "Ctrl+" : "") + (k.shift ? "Shift+" : "") + (k.alt ? "Alt+" : "") };
        if ((k.vk >= 'A' && k.vk <= 'Z') || (k.vk >= '0' && k.vk <= '9')) return out + static_cast<char>(k.vk);
        if (k.vk >= 0x70 && k.vk <= 0x7B) return out + "F" + std::to_string(k.vk - 0x70 + 1);
        for (const auto& [name, code] : keyNames()) if (code == k.vk) return out + name;
        return out + "?";
    }

    bool sameKey(const Key& a, const Key& b) { return a.vk == b.vk && a.ctrl == b.ctrl && a.shift == b.shift && a.alt == b.alt; }
}

class CommandTable
{
public:
    bool add(int id, const std::string& text, const std::string& shortcut)
    {
        if (m_commands.count(id)) return false;
        Command c{ text, false, Key{ 0 }, true, false };
        if (!shortcut.empty())
        {
            if (!parseKey(shortcut, c.key)) return false;
            for (const auto& [otherId, other] : m_commands) if (other.hasKey && sameKey(other.key, c.key)) return false;
            c.hasKey = true;
        }
        m_commands[id] = c;
        return true;
    }

    void setEnabled(int id, bool enabled) { if (auto it{ m_commands.find(id) }; it != m_commands.end()) it->second.enabled = enabled; }
    void setChecked(int id, bool checked) { if (auto it{ m_commands.find(id) }; it != m_commands.end()) it->second.checked = checked; }

    int translate(const Key& k) const
    {
        for (const auto& [id, c] : m_commands) if (c.hasKey && c.enabled && sameKey(c.key, k)) return id;
        return 0;
    }

    std::string menuLine(int id) const
    {
        auto it{ m_commands.find(id) };
        if (it == m_commands.end()) return "";
        const Command& c{ it->second };
        std::string line{ (c.checked ? "[x] " : "") + c.text };
        if (c.hasKey) line += "\t" + formatKey(c.key);
        if (!c.enabled) line += " (disabled)";
        return line;
    }

private:
    struct Command { std::string text; bool hasKey; Key key; bool enabled; bool checked; };
    std::map<int, Command> m_commands;
};

class RecentFiles
{
public:
    explicit RecentFiles(std::size_t max) : m_max{ std::min<std::size_t>(max, 9) } {}

    void add(const std::string& path)
    {
        remove(path);
        m_items.insert(m_items.begin(), path);
        if (m_items.size() > m_max) m_items.resize(m_max);
    }

    void remove(const std::string& path)
    {
        const std::string key{ lower(path) };
        m_items.erase(std::remove_if(m_items.begin(), m_items.end(), [&](const std::string& p) { return lower(p) == key; }), m_items.end());
    }

    const std::vector<std::string>& items() const { return m_items; }

    std::vector<std::string> menuItems(std::size_t maxChars) const
    {
        std::vector<std::string> out;
        for (std::size_t i{ 0 }; i < m_items.size(); ++i)
        {
            std::string shown;
            for (char c : shorten(m_items[i], maxChars)) { shown += c; if (c == '&') shown += '&'; }
            out.push_back("&" + std::to_string(i + 1) + " " + shown);
        }
        return out;
    }

    static std::string shorten(const std::string& path, std::size_t maxChars)
    {
        if (path.size() <= maxChars) return path;
        std::vector<std::string> parts;
        std::stringstream in{ path };
        for (std::string p; std::getline(in, p, '\\');) parts.push_back(p);
        for (std::size_t k{ 2 }; k < parts.size(); ++k)
        {
            std::string candidate{ parts[0] + "\\...\\" };
            for (std::size_t j{ k }; j < parts.size(); ++j) candidate += (j > k ? "\\" : "") + parts[j];
            if (candidate.size() <= maxChars) return candidate;
        }
        const std::size_t keep{ maxChars > 3 ? maxChars - 3 : 0 };
        return "..." + path.substr(path.size() - keep);
    }

    std::string save() const
    {
        std::string out;
        for (const std::string& p : m_items) out += p + "\n";
        return out;
    }

    void load(const std::string& text)
    {
        m_items.clear();
        std::istringstream in{ text };
        for (std::string line; std::getline(in, line);)
        {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            if (line.empty() || m_items.size() == m_max) continue;
            const std::string key{ lower(line) };
            if (std::none_of(m_items.begin(), m_items.end(), [&](const std::string& p) { return lower(p) == key; })) m_items.push_back(line);
        }
    }

private:
    std::size_t m_max;
    std::vector<std::string> m_items;
};

unitTests:
using Lines = std::vector<std::string>;
TEST("commands and shortcuts") {
    CommandTable t;
    CHECK(t.add(1, "&Save", "ctrl+s")); CHECK(t.add(2, "&Open...", "Ctrl+O")); CHECK(t.add(3, "&Status Bar", "")); CHECK(t.add(4, "&Refresh", "F5"));
    CHECK(!t.add(1, "Again", "Ctrl+N")); CHECK(!t.add(5, "Search", "Control+S")); CHECK(!t.add(6, "Bad", "Ctrl+??"));
    CHECK_EQ(t.translate({ 'S', true }), 1); CHECK_EQ(t.translate({ 'S', true, true }), 0); CHECK_EQ(t.translate({ 0x74 }), 4); CHECK_EQ(t.translate({ 'S' }), 0);
    t.setEnabled(1, false); CHECK_EQ(t.translate({ 'S', true }), 0);
}
TEST("menu lines") {
    CommandTable t; t.add(1, "&Save", "ctrl+shift+s"); t.add(3, "&Status Bar", "");
    CHECK_EQ(t.menuLine(1), std::string("&Save\tCtrl+Shift+S")); t.setEnabled(1, false); CHECK_EQ(t.menuLine(1), std::string("&Save\tCtrl+Shift+S (disabled)"));
    t.setChecked(3, true); CHECK_EQ(t.menuLine(3), std::string("[x] &Status Bar")); CHECK_EQ(t.menuLine(99), std::string(""));
}
TEST("recent files") {
    RecentFiles r{ 3 }; r.add("C:\\a.txt"); r.add("C:\\b.txt"); r.add("C:\\c.txt"); r.add("c:\\A.TXT");
    CHECK_EQ(r.items(), (Lines{ "c:\\A.TXT", "C:\\c.txt", "C:\\b.txt" })); r.add("C:\\d.txt"); CHECK_EQ(r.items().size(), std::size_t{ 3 }); CHECK_EQ(r.items().back(), std::string("C:\\c.txt"));
    r.remove("C:\\C.TXT"); CHECK_EQ(r.items(), (Lines{ "C:\\d.txt", "c:\\A.TXT" }));
}
TEST("shortening") {
    const std::string p = "C:\\Users\\Sam\\Documents\\Projects\\Xenon\\notes.txt";
    CHECK_EQ(RecentFiles::shorten(p, 60), p); CHECK_EQ(RecentFiles::shorten(p, 30), std::string("C:\\...\\Xenon\\notes.txt"));
    CHECK_EQ(RecentFiles::shorten(p, 31), std::string("C:\\...\\Projects\\Xenon\\notes.txt")); CHECK_EQ(RecentFiles::shorten(p, 16), std::string("C:\\...\\notes.txt"));
    CHECK_EQ(RecentFiles::shorten(p, 10), std::string("...tes.txt"));
}
TEST("menu items") {
    RecentFiles r{ 9 }; r.add("D:\\R&D\\plan.txt"); r.add("C:\\Users\\Sam\\Documents\\Projects\\Xenon\\notes.txt");
    CHECK_EQ(r.menuItems(30), (Lines{ "&1 C:\\...\\Xenon\\notes.txt", "&2 D:\\R&&D\\plan.txt" }));
}
TEST("saving and loading") {
    RecentFiles r{ 2 }; r.add("C:\\x.txt"); r.add("C:\\y.txt"); CHECK_EQ(r.save(), std::string("C:\\y.txt\nC:\\x.txt\n"));
    RecentFiles s{ 2 }; s.load("C:\\one.txt\r\n\r\nc:\\ONE.txt\r\nC:\\two.txt\r\nC:\\three.txt\r\n"); CHECK_EQ(s.items(), (Lines{ "C:\\one.txt", "C:\\two.txt" }));
}

